import {addCat, findCatById, listAllCats, deleteCatById, putCatById, findCatByOwnerId} from "../models/cat-model.js";

const getCat = async (req, res) => {
  res.json(await listAllCats());
};

const getCatById = async (req, res) => {
  const cat = await findCatById(req.params.id);
  if (cat) {
    res.json(cat);
  } else {
    res.sendStatus(404);
  }
};

const postCat = async (req, res) => {
  try {
    // Add the filename generated by Multer directly to req.body
    req.body.filename = req.file ? req.file.filename : null;

    console.log('Form Data:', req.body); // Log form data
    console.log('File Data:', req.file);

    const result = await addCat(req.body);
    if (result.cat_id) {
      res.status(201);
      res.json({ message: 'New cat added.', result });
    } else {
      res.status(400).json({ message: 'Failed to add cat.' });
    }
  } catch (error) {
    console.error('Error in postCat:', error.message); // Log the error message
    res.status(500).json({ message: error.message });
  }
};

const putCat = async (req, res) => {
  try {
    // Validate input
    if (!req.body || Object.keys(req.body).length === 0) {
      return res.status(400).json({ message: 'No data provided for update.' });
    }

    const updateCat = await putCatById(req.body, req.params.id);
    if (updateCat) {
      res.status(200).json({ message: 'Cat item updated.', updateCat });
    } else {
      res.status(404).json({ message: 'Cat not found.' });
    }
  } catch (error) {
    console.error('Error in putCat:', error.message); // Log the error
    res.status(500).json({ message: 'Internal server error.' });
  }
};

const deleteCat = async (req, res) => {
  // not implemented in this example, this is future homework
  const deleteCat = await deleteCatById(req.params.id);
  if (deleteCat) {
    res.status(200).json({message: 'Cat item deleted.'});
  } else {
    res.sendStatus(404);
  }
};

const getCatByOwnerId = async (req, res) => {
  const cat = findCatByOwnerId(req.params.id);
  if (cat) {
    res.json(await cat);
  } else {
    res.sendStatus(404);
  }
};

export {getCat, getCatById, postCat, putCat, deleteCat, getCatByOwnerId};